      const row = node('article', 'day-row'), label = node('div', '');
      label.append(node('div', 'day-name', group.key === dayKey(Date.now()) ? 'Today' : fmt(primary.startTime, { weekday: 'long' })), node('div', 'day-date', fmt(primary.startTime, { month: 'short', day: 'numeric' })));
      const outlook = node('div', 'day-outlook'); outlook.append(icon(weatherIcon(primary), true), node('span', '', primary.shortForecast));
      const temperatures = node('div', 'day-temps'); temperatures.setAttribute('aria-label', `High ${day ? day.temperature : 'unavailable'}, low ${night ? night.temperature : 'unavailable'} degrees Fahrenheit`);
      temperatures.append(node('span', 'day-high', day ? day.temperature + '°' : '—'), node('span', 'temp-range'), node('span', 'day-low', night ? night.temperature + '°' : '—'));
      const rain = node('div', 'day-rain'); rain.title = primary.name + ' precipitation chance';
      rain.append(icon('drop'), node('span', '', present(primary.probabilityOfPrecipitation?.value) ? primary.probabilityOfPrecipitation.value + '%' : '—'));
      row.append(label, outlook, temperatures, rain, node('div', 'day-wind', primary.windSpeed || '—')); $('days').append(row);
