.current h2{font-size:36px;line-height:1.15;margin-bottom:14px}
.high-low{display:flex;flex-wrap:wrap;gap:8px 22px;font-size:26px;line-height:1.3;font-weight:450;margin-bottom:14px}
.high-low span{margin:0;color:#edf2e9}
.high-low .daily-low{color:#ccded8}
.high-low .feels-like{flex-basis:100%;font-size:16px;font-weight:400;color:#bdcfca}
.today-summary{font-size:21px;line-height:1.35;max-width:560px;margin-bottom:18px;color:#d2dfd8}
.current-details{font-size:15px}
.hourly-heading h2{font-size:18px}
.hourly-heading>span{font-size:13px}
.hour time{font-size:18px;font-weight:500;color:#e6eee7}
.hour .hour-rain{font-size:13px}
.hour .hour-wind{font-size:12px;color:#bdd0c9}
.temp-range{background:linear-gradient(90deg,#d1d7ab,#b4b2d1,#82bab7)}
